(function(){
  const svg = document.getElementById("lift-svg");
  const stepBtn = document.getElementById("lift-step");
  const resetBtn = document.getElementById("lift-reset");
  const phaseLabel = document.getElementById("lift-phase");
  const out = document.getElementById("lift-out");
  if(!svg) return;
  const W = 760, H = 260;
  const initial = [4, 8, 3, 5, 9, 1, 6, 2];
  const phaseNames = [
    "0 of 4 — initial signal s_n",
    "1 of 4 — split into evens / odds",
    "2 of 4 — predict: d_n = s^(o)_n − s^(e)_n",
    "3 of 4 — update: a_n = s^(e)_n + d_n / 2",
    "4 of 4 — done (Haar pair (a, d))"
  ];
  let phase = 0;
  function evens(){ return initial.filter((_,i)=> i%2===0); }
  function odds(){ return initial.filter((_,i)=> i%2===1); }
  function details(){
    const e = evens(), o = odds();
    return o.map((v,i)=> v - e[i]);
  }
  function approxes(){
    const e = evens(), d = details();
    return e.map((v,i)=> v + d[i]/2);
  }
  function chip(x, y, val, color, label){
    svg.appendChild(SVG("rect",{
      x: x-22, y: y-16, width:44, height:32, rx:6,
      fill: color, "fill-opacity":"0.18", stroke: color, "stroke-width":1.4
    }));
    const t = SVG("text",{x, y: y+5, "text-anchor":"middle","font-size":13, fill:"var(--ink)","font-weight":600});
    t.textContent = (typeof val === "number") ? (Number.isInteger(val)? val.toFixed(0) : val.toFixed(2)) : String(val);
    svg.appendChild(t);
    if(label){
      const lab = SVG("text",{x, y: y-22, "text-anchor":"middle","font-size":10, fill:"var(--mute)"});
      lab.textContent = label;
      svg.appendChild(lab);
    }
  }
  function arrow(x1,y1,x2,y2,color){
    drawArrow(svg,[x1,y1],[x2,y2],{color, width:1.2, pad1:6, pad2:8, markerId:"lift-arr-"+color.replace(/[^a-z]/gi,"")});
  }
  function draw(){
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    phaseLabel.textContent = "phase " + phaseNames[phase];
    const padL = 60, padR = 30;
    const N = initial.length;
    const span = (W-padL-padR);
    const dx = span / N;
    // Row labels
    function rowLabel(y, txt, col){
      const t = SVG("text",{x: padL-12, y: y+5, "text-anchor":"end","font-size":12, fill: col || "var(--mute)"});
      t.textContent = txt;
      svg.appendChild(t);
    }
    if(phase === 0){
      rowLabel(60, "input s", "var(--ink)");
      for(let i=0;i<N;i++){
        chip(padL + (i+0.5)*dx, 60, initial[i], "var(--blue)", "s_"+i);
      }
      out.textContent = "Input signal of length " + N + ".  Click \"step\" to apply lazy split → predict → update.";
    }
    else if(phase >= 1){
      // Top row: input
      rowLabel(45, "input s", "var(--mute)");
      for(let i=0;i<N;i++){
        chip(padL + (i+0.5)*dx, 45, initial[i], "var(--mute)", null);
      }
      // Mid row: evens (left half), odds (right half)
      const half = N/2;
      const e = evens(), o = odds();
      rowLabel(120, "evens s^(e)", "var(--cyan)");
      for(let i=0;i<half;i++){
        chip(padL + (i+0.5)*(span/2)/half * 1, 120, e[i], "var(--cyan)", "i="+i);
      }
      rowLabel(120, "  ", "var(--mute)");
      const oddsX0 = padL + span/2 + 10;
      const oddsW = span/2 - 10;
      // separate "odds" label
      const lab2 = SVG("text",{x: oddsX0 - 20, y: 125, "text-anchor":"end","font-size":12, fill:"var(--yellow)"});
      lab2.textContent = "odds s^(o)";
      svg.appendChild(lab2);
      for(let i=0;i<half;i++){
        chip(oddsX0 + (i+0.5)*oddsW/half, 120, o[i], "var(--yellow)", "i="+i);
      }
      // Arrows from input to split
      if(phase === 1){
        for(let i=0;i<N;i++){
          const sx = padL + (i+0.5)*dx, sy = 45+18;
          if(i%2===0){
            const tx = padL + (i/2+0.5)*(span/2)/half, ty = 120-18;
            arrow(sx, sy, tx, ty, "var(--cyan)");
          } else {
            const tx = oddsX0 + (((i-1)/2)+0.5)*oddsW/half, ty = 120-18;
            arrow(sx, sy, tx, ty, "var(--yellow)");
          }
        }
        out.textContent = "Lazy split — interleave done.  Even-indexed s_{2n} go to s^(e); odd-indexed s_{2n+1} go to s^(o). Same numbers, just rearranged.";
      }
      // Bottom row: details (after predict) and/or approxes (after update)
      if(phase >= 2){
        const d = details();
        const a = (phase >= 3) ? approxes() : null;
        rowLabel(200, "details d", "var(--pink)");
        for(let i=0;i<half;i++){
          chip(padL + (i+0.5)*(span/2)/half, 200, d[i], "var(--pink)", "n="+i);
        }
        if(phase >= 3){
          const lab3 = SVG("text",{x: oddsX0 - 20, y: 205, "text-anchor":"end","font-size":12, fill:"var(--green)"});
          lab3.textContent = "approx a";
          svg.appendChild(lab3);
          for(let i=0;i<half;i++){
            chip(oddsX0 + (i+0.5)*oddsW/half, 200, a[i], "var(--green)", "n="+i);
          }
        }
        if(phase === 2){
          // arrows: o_n minus e_n -> d_n
          for(let i=0;i<half;i++){
            const ex = padL + (i+0.5)*(span/2)/half, ey = 120+18;
            const ox = oddsX0 + (i+0.5)*oddsW/half, oy = 120+18;
            const tx = padL + (i+0.5)*(span/2)/half, ty = 200-18;
            arrow(ex, ey, tx, ty, "var(--mute)");
            arrow(ox, oy, tx, ty, "var(--pink)");
          }
          out.textContent = "Predict step — d_n = s^(o)_n − s^(e)_n  (each odd minus its left neighbour).  d = [" + d.join(", ") + "].  d is now the residual the predictor missed.";
        } else if(phase === 3){
          // arrows: e_n + d_n/2 -> a_n
          for(let i=0;i<half;i++){
            const ex = padL + (i+0.5)*(span/2)/half, ey = 120+18;
            const dx2 = padL + (i+0.5)*(span/2)/half, dy2 = 200-18;
            const tx = oddsX0 + (i+0.5)*oddsW/half, ty = 200-18;
            arrow(ex, ey, tx, ty, "var(--mute)");
            arrow(dx2, dy2 - 6, tx, ty, "var(--green)");
          }
          out.textContent = "Update step — a_n = s^(e)_n + ½ d_n = (s_{2n} + s_{2n+1})/2.  a = [" + a.map(x=>x.toFixed(2)).join(", ") + "].  Local averages (low-pass).";
        } else if(phase === 4){
          out.textContent = "Forward Haar via lifting complete.  a = [" + a.map(x=>x.toFixed(2)).join(", ") + "]  (averages).  d = [" + d.join(", ") + "]  (differences).  Inverse: undo update first (s^(e) = a − d/2), then undo predict (s^(o) = s^(e) + d).";
        }
      }
    }
  }
  stepBtn.addEventListener("click", ()=>{
    phase = Math.min(4, phase+1);
    draw();
  });
  resetBtn.addEventListener("click", ()=>{
    phase = 0;
    draw();
  });
  draw();
})();

