(function(){
  const svg = document.getElementById("bio-svg");
  const buttons = svg.parentElement.querySelectorAll("button[data-bio]");
  const out = document.getElementById("bio-out");
  if(!svg) return;
  const W = 760, H = 260;
  // Filters as { analysis: [...], synthesis: [...], symmetric, vmA, vmS, name }
  const families = {
    db4: {
      analysis: [0.2303778133088964, 0.7148465705529154, 0.6308807679298587,
        -0.0279837694168599, -0.1870348117190931, 0.0308413818355607,
         0.0328830116668852, -0.0105974017850690],
      synthesis: [0.2303778133088964, 0.7148465705529154, 0.6308807679298587,
        -0.0279837694168599, -0.1870348117190931, 0.0308413818355607,
         0.0328830116668852, -0.0105974017850690],
      symmetric: false,
      vmA: 4, vmS: 4,
      lengthA: 8, lengthS: 8,
      name: "db4 (Daubechies 4)",
      note: "orthogonal: analysis = synthesis exactly (h̃ = h). Asymmetric — Daubechies' theorem forbids symmetric orthogonal compactly-supported wavelets except Haar."
    },
    cdf53: {
      // CDF 5/3 (LeGall). Analysis low-pass length 5, synthesis length 3.
      analysis: [-0.125, 0.25, 0.75, 0.25, -0.125],
      synthesis: [0.25, 0.5, 0.25],
      // Multiplied by sqrt(2) for L2 norm; here we just plot the filter taps as listed.
      symmetric: true,
      vmA: 2, vmS: 2,
      lengthA: 5, lengthS: 3,
      name: "CDF 5/3 (JPEG2000 lossless)",
      note: "biorthogonal: analysis ≠ synthesis. Both filters symmetric about centre — linear-phase. Integer-friendly: lifting form gives lossless reconstruction with floor-divisions only."
    },
    cdf97: {
      analysis: [0.0378284555, -0.0238494650, -0.1106244044, 0.3774028557,
                 0.8526986790, 0.3774028557, -0.1106244044, -0.0238494650, 0.0378284555],
      synthesis: [-0.0645388826, -0.0406894176, 0.4180922732, 0.7884856164,
                   0.4180922732, -0.0406894176, -0.0645388826],
      symmetric: true,
      vmA: 4, vmS: 4,
      lengthA: 9, lengthS: 7,
      name: "CDF 9/7 (JPEG2000 lossy)",
      note: "biorthogonal: analysis length 9, synthesis length 7. Both symmetric (linear-phase). Inside the FBI fingerprint codec and JPEG2000's lossy mode."
    }
  };
  function plot(filter, x0, x1, y0, y1, color, label){
    const n = filter.length;
    let yMax = 0;
    for(const v of filter) if(Math.abs(v) > yMax) yMax = Math.abs(v);
    yMax = Math.max(yMax, 0.5) * 1.1;
    const yMid = (y0+y1)/2;
    const xs = (i)=> x0 + (i+0.5)*(x1-x0)/n;
    const ys = (v)=> yMid - v/yMax * (y1-y0)/2 * 0.85;
    // box
    svg.appendChild(SVG("rect",{x:x0,y:y0,width:x1-x0,height:y1-y0,fill:"transparent",stroke:"var(--line)","stroke-width":1}));
    // zero axis
    svg.appendChild(SVG("line",{x1:x0,y1:yMid,x2:x1,y2:yMid,stroke:"var(--line)","stroke-width":1,"stroke-dasharray":"3 3"}));
    // stems
    for(let i=0;i<n;i++){
      const xi = xs(i), yi = ys(filter[i]);
      svg.appendChild(SVG("line",{x1:xi,y1:yMid,x2:xi,y2:yi,stroke:color,"stroke-width":1.5}));
      svg.appendChild(SVG("circle",{cx:xi,cy:yi,r:3.5,fill:color,stroke:"#0b0f16","stroke-width":1}));
    }
    // label
    const t = SVG("text",{x: x0+8, y: y0+14, "font-size":12, fill: color});
    t.textContent = label;
    svg.appendChild(t);
    // n label
    const t2 = SVG("text",{x: x1-8, y: y0+14, "font-size":11, fill: "var(--mute)", "text-anchor":"end"});
    t2.textContent = "length " + n;
    svg.appendChild(t2);
  }
  function draw(key){
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    const f = families[key];
    const padL = 30, padR = 30, padT = 30, padB = 30, gap = 30;
    const colW = (W - padL - padR - gap)/2;
    const rowH = (H - padT - padB);
    plot(f.analysis, padL, padL+colW, padT, padT+rowH, "var(--cyan)", "analysis  h̃[n]");
    plot(f.synthesis, padL+colW+gap, padL+colW+gap+colW, padT, padT+rowH, "var(--yellow)", "synthesis  h[n]");
    // Title
    const title = SVG("text",{x: W/2, y: 18, "text-anchor":"middle","font-size":12, fill:"var(--ink)"});
    title.textContent = f.name + "  ·  " + (f.symmetric ? "symmetric (linear-phase)" : "asymmetric");
    svg.appendChild(title);
    out.textContent = "analysis length " + f.lengthA + ", synthesis length " + f.lengthS +
      "  ·  vanishing moments: ψ̃ has " + f.vmA + ", ψ has " + f.vmS +
      "\n" + f.note;
  }
  buttons.forEach(b=>{
    b.addEventListener("click", ()=>{
      buttons.forEach(x=>x.classList.remove("active"));
      b.classList.add("active");
      draw(b.dataset.bio);
    });
  });
  draw("db4");
})();

