  function haarDWT(a){
    const levels = [];
    let cur = a.slice();
    while(cur.length > 1){
      const n = cur.length;
      const A = new Array(n/2), D = new Array(n/2);
      for(let k=0;k<n/2;k++){
        A[k] = (cur[2*k]+cur[2*k+1])/Math.SQRT2;
        D[k] = (cur[2*k]-cur[2*k+1])/Math.SQRT2;
      }
      levels.push(D);  // index 0 is finest
