    yt.textContent = "log₂ max |d_{j,k}|";
    svg.appendChild(yt);
    // Empirical points
    for(let j=0;j<J;j++){
      if(yLog[j] <= -40) continue;
      const cx = xs(j), cy = ys(yLog[j]);
      svg.appendChild(SVG("circle",{cx, cy, r:4, fill:"var(--cyan)", stroke:"var(--bg)","stroke-width":1}));
    }
    let dPath = "";
    for(let j=0;j<J;j++){
      if(yLog[j] <= -40) continue;
      const cx = xs(j), cy = ys(yLog[j]);
      dPath += (dPath===""?"M":"L")+cx+" "+cy+" ";
    }
    svg.appendChild(SVG("path",{d:dPath, fill:"none", stroke:"var(--cyan)","stroke-width":1.5,"stroke-opacity":"0.6"}));
