        const anchor = valid[anchorIdx];
        const c0 = anchor.v - slope*anchor.j;  // log2|d_0| extrapolation
        const x0p = xs(0), y0p = ys(c0);
        const x1p = xs(J-1), y1p = ys(c0 + slope*(J-1));
        // Clip to the SVG viewport (predicted line might exit)
