        function clip(x0, y0, x1, y1){
          // Clip line segment to [yClipMin, yClipMax]
          if(y0 >= yClipMin && y0 <= yClipMax && y1 >= yClipMin && y1 <= yClipMax) return [x0,y0,x1,y1];
          // Simple clip: skip drawing if both endpoints out
