          let nx0=x0, ny0=y0, nx1=x1, ny1=y1;
          if(ny0 > yClipMax){ nx0 = x0 + (yClipMax-y0)*(x1-x0)/(y1-y0); ny0 = yClipMax; }
          if(ny1 > yClipMax){ nx1 = x0 + (yClipMax-y0)*(x1-x0)/(y1-y0); ny1 = yClipMax; }
          if(ny0 < yClipMin){ nx0 = x0 + (yClipMin-y0)*(x1-x0)/(y1-y0); ny0 = yClipMin; }
          if(ny1 < yClipMin){ nx1 = x0 + (yClipMin-y0)*(x1-x0)/(y1-y0); ny1 = yClipMin; }
          return [nx0,ny0,nx1,ny1];
        }
        const clipped = clip(x0p,y0p,x1p,y1p);
        if(clipped){
          const [cx0,cy0,cx1,cy1] = clipped;
          svg.appendChild(SVG("line",{x1:cx0,y1:cy0,x2:cx1,y2:cy1,stroke:"var(--yellow)","stroke-width":1.4,"stroke-dasharray":"6 4"}));
          const lab = SVG("text",{x:cx1-8, y:cy1-6, "font-size":11, "text-anchor":"end", fill:"var(--yellow)"});
          lab.textContent = isCapped
            ? "Haar-limited slope = " + slope.toFixed(1) + " (saturated; ideal α+½ = " + idealSlope.toFixed(1) + ")"
            : "predicted slope (α+½) = " + slope.toFixed(1);
          svg.appendChild(lab);
        }
      }
    }
    const hdr = SVG("text",{x: W/2, y: 18, "text-anchor":"middle","font-size":12, fill:"var(--ink)"});
    hdr.textContent = sig.label + "   →   Haar wavelet coefficient decay";
    svg.appendChild(hdr);
    out.textContent = sig.note;
  }
  buttons.forEach(b=>{
    b.addEventListener("click", ()=>{
      buttons.forEach(x=>x.classList.remove("active"));
      b.classList.add("active");
      draw(b.dataset.sig);
    });
  });
  // Default to "lin" — the cleanest pedagogical pairing (slope exactly matches the Haar limit at 1.5).
  buttons.forEach(b=>{ if(b.dataset.sig==="lin") b.classList.add("active"); });
  draw("lin");
})();

